(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.016+t*0.32)*11 + Math.cos((x-y)*0.009-t*0.18)*7;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*6 + Math.cos(sy*0.03+t*0.35)*5;
  const w2y = Math.cos(sy*0.022+t*0.38)*7 + Math.sin(sx*0.028-t*0.42)*4;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*55, 0.14, 1.4, 0.8],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+1)*45, 0.11, 2.1, 1.15]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const w1 = Math.sin(d*f-t*sp), w2 = Math.sin(d*f*1.618-t*sp*0.618+0.5);
    aS += (w1+w2*0.3)*w; iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    hS += Math.sin(d*f*0.5-t*sp*0.4+Math.atan2(fy-sY,fx-sX)*2)*w*0.5;
  }
  const act=aS/8, inh=iS/8, har=hS/8;
  const bg1 = (Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2;
  const bg2 = Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(fx*0.08+t*1.8)*Math.sin(fy*0.07-t*1.4)*0.3;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5), sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.08-ang*2+t*0.9)*0.5, spiral=(sp1+sp2)*0.4+sp3;
  const micro = (Math.sin(fx*0.3+fy*0.2+t*3)*Math.sin(fx*0.25-fy*0.3-t*2.5))*0.15;
  const cell = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const rd1 = act-inh*0.7+bg*0.3+spiral;
  const rd2 = act*0.5+inh*0.3+har*0.4+micro;
  const reaction = Math.tanh(rd1*2.2)*0.7+Math.tanh(rd2*1.8)*0.3;
  const blend = reaction*0.7+cell*0.2+micro*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,85],[18,95,115],[25,150,135],[80,175,120],
    [180,185,70],[210,155,55],[195,95,60],[165,50,65],[120,25,55],
    [65,15,48],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,Math.abs(reaction)-0.5)*0.3;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*60)|0)
  ];
}
